sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    /*
     * Return to Check My Records ASEAN.
     */
    c.goBack = function() {
        $window.location.href =
            "?id=check_my_records_asean";
    };

    /*
     * Open attachment in a new browser tab.
     */
    c.viewAttachment = function(attachment) {

        if (
            !attachment ||
            !attachment.viewUrl
        ) {
            return;
        }

        $window.open(
            attachment.viewUrl,
            "_blank"
        );
    };

    /*
     * Download attachment.
     */
    c.downloadAttachment = function(attachment) {

        if (
            !attachment ||
            !attachment.downloadUrl
        ) {
            return;
        }

        var downloadLink =
            document.createElement("a");

        downloadLink.href =
            attachment.downloadUrl;

        downloadLink.download =
            attachment.fileName || "attachment";

        downloadLink.target = "_blank";

        document.body.appendChild(
            downloadLink
        );

        downloadLink.click();

        document.body.removeChild(
            downloadLink
        );
    };

    /*
     * Select an icon based on attachment type.
     */
    c.getAttachmentIcon = function(
        contentType,
        fileName
    ) {

        var type =
            (contentType || "").toLowerCase();

        var name =
            (fileName || "").toLowerCase();

        if (
            type.indexOf("pdf") > -1 ||
            name.indexOf(".pdf") > -1
        ) {
            return "fa-file-pdf-o";
        }

        if (
            type.indexOf("image") > -1 ||
            /\.(png|jpg|jpeg|gif|bmp|webp)$/.test(name)
        ) {
            return "fa-file-image-o";
        }

        if (
            type.indexOf("spreadsheet") > -1 ||
            type.indexOf("excel") > -1 ||
            /\.(xls|xlsx|csv)$/.test(name)
        ) {
            return "fa-file-excel-o";
        }

        if (
            type.indexOf("word") > -1 ||
            /\.(doc|docx)$/.test(name)
        ) {
            return "fa-file-word-o";
        }

        if (
            type.indexOf("presentation") > -1 ||
            type.indexOf("powerpoint") > -1 ||
            /\.(ppt|pptx)$/.test(name)
        ) {
            return "fa-file-powerpoint-o";
        }

        if (
            type.indexOf("zip") > -1 ||
            /\.(zip|rar|7z)$/.test(name)
        ) {
            return "fa-file-archive-o";
        }

        if (
            type.indexOf("text") > -1 ||
            /\.(txt|log)$/.test(name)
        ) {
            return "fa-file-text-o";
        }

        return "fa-file-o";
    };

};

sp_widget.css:
.view-registration-container {
    min-height: 100vh;
    padding: 25px;
    background: #f5f7fa;
}

/* Main card */
.registration-card {
    overflow: hidden;
    background: #ffffff;
    border: 1px solid #dfe3e8;
    border-radius: 8px;
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.08);
}

/* Header */
.registration-header {
    padding: 25px 30px;
    background: #ffffff;
    border-bottom: 1px solid #e6e6e6;
}

.registration-header h2 {
    margin: 0;
    color: #f58220;
    font-size: 24px;
    font-weight: 600;
}

.registration-header h2 i {
    margin-right: 10px;
}

.request-number {
    margin-top: 10px;
    color: #555555;
    font-size: 15px;
    font-weight: 500;
}

/* Body */
.registration-body {
    padding: 30px;
}

.form-group {
    margin-bottom: 22px;
}

.form-group label {
    display: block;
    margin-bottom: 7px;
    color: #444444;
    font-size: 14px;
    font-weight: 600;
}

/* Normal fields */
.form-control {
    width: 100%;
    height: 42px;
    padding: 8px 12px;
    color: #333333;
    background: #f8f9fb !important;
    border: 1px solid #d9dee5;
    border-radius: 4px;
    box-shadow: none;
    cursor: default;
}

.form-control:focus {
    border-color: #d9dee5;
    outline: none;
    box-shadow: none;
}

input.form-control[readonly],
textarea.form-control[readonly] {
    color: #333333;
    background: #f8f9fb !important;
    cursor: default;
}

.readonly-textarea {
    min-height: 120px;
    height: auto;
    padding: 12px;
    overflow-y: auto;
    line-height: 1.6;
    white-space: pre-wrap;
    overflow-wrap: break-word;
    resize: vertical;
}

/* Boolean */
.checkbox-field {
    display: flex;
    align-items: center;
    height: 42px;
    padding: 0 12px;
    background: #f8f9fb;
    border: 1px solid #d9dee5;
    border-radius: 4px;
}

.checkbox-field input {
    margin: 0 10px 0 0;
}

.checkbox-field span {
    color: #333333;
    font-size: 14px;
}

/* Common section heading */
.section-heading {
    display: flex;
    align-items: center;
    margin-bottom: 20px;
    color: #f58220;
    font-size: 20px;
    font-weight: 600;
}

.section-heading > i {
    margin-right: 8px;
}

.section-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 26px;
    height: 26px;
    margin-left: 10px;
    padding: 0 8px;
    color: #ffffff;
    background: #f58220;
    border-radius: 13px;
    font-size: 12px;
    font-weight: 600;
}

/* Attachments */
.attachments-section {
    clear: both;
    margin-top: 15px;
    padding-top: 25px;
    border-top: 1px solid #e6e6e6;
}

.attachment-list {
    width: 100%;
}

.attachment-card {
    display: flex;
    align-items: center;
    width: 100%;
    margin-bottom: 12px;
    padding: 14px 16px;
    background: #ffffff;
    border: 1px solid #dfe3e8;
    border-left: 4px solid #f58220;
    border-radius: 5px;
    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease,
        transform 0.2s ease;
}

.attachment-card:hover {
    border-color: #f5b075;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.07);
    transform: translateY(-1px);
}

.attachment-icon {
    display: flex;
    flex: 0 0 48px;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    margin-right: 15px;
    color: #f58220;
    background: #fff5ec;
    border-radius: 6px;
    font-size: 25px;
}

.attachment-information {
    flex: 1;
    min-width: 0;
}

.attachment-name {
    overflow: hidden;
    margin-bottom: 7px;
    color: #333333;
    font-size: 14px;
    font-weight: 600;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.attachment-metadata {
    display: flex;
    flex-wrap: wrap;
    color: #666666;
    font-size: 12px;
    gap: 8px 18px;
}

.attachment-metadata span {
    display: inline-flex;
    align-items: center;
}

.attachment-metadata i {
    margin-right: 5px;
    color: #777777;
}

.attachment-actions {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    margin-left: 15px;
    gap: 8px;
}

.attachment-view-btn,
.attachment-download-btn {
    padding: 7px 13px;
    border-radius: 4px;
    font-size: 13px;
    font-weight: 600;
    transition:
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}

.attachment-view-btn {
    color: #f58220;
    background: #ffffff;
    border: 1px solid #f58220;
}

.attachment-view-btn:hover,
.attachment-view-btn:focus {
    color: #ffffff;
    background: #f58220;
    border-color: #f58220;
    outline: none;
}

.attachment-download-btn {
    color: #ffffff;
    background: #f58220;
    border: 1px solid #f58220;
}

.attachment-download-btn:hover,
.attachment-download-btn:focus {
    color: #ffffff;
    background: #d96b0f;
    border-color: #d96b0f;
    outline: none;
}

.attachment-actions i {
    margin-right: 5px;
}

/* Journal section */
.journal-section {
    clear: both;
    margin-top: 30px;
    padding-top: 25px;
    border-top: 1px solid #e6e6e6;
}

.journal-group {
    margin-bottom: 28px;
}

.journal-title {
    display: flex;
    align-items: center;
    margin: 0 0 14px;
    padding-bottom: 9px;
    color: #333333;
    font-size: 17px;
    font-weight: 600;
    border-bottom: 1px solid #eceff2;
}

.journal-title > i {
    margin-right: 9px;
    color: #f58220;
}

.journal-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 25px;
    height: 25px;
    margin-left: 9px;
    padding: 0 8px;
    color: #ffffff;
    background: #f58220;
    border-radius: 13px;
    font-size: 12px;
    font-weight: 600;
}

.journal-entry {
    margin-bottom: 14px;
    overflow: hidden;
    background: #ffffff;
    border: 1px solid #dfe3e8;
    border-left: 4px solid #f58220;
    border-radius: 5px;
}

.comments-entry {
    border-left-color: #f58220;
}

.work-notes-entry {
    border-left-color: #5c6bc0;
}

.journal-entry-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    color: #555555;
    background: #f8f9fb;
    border-bottom: 1px solid #e6e9ed;
    font-size: 12px;
}

.journal-user {
    font-weight: 600;
}

.journal-user i,
.journal-date i {
    margin-right: 5px;
}

.journal-date {
    color: #666666;
}

.journal-entry-body {
    min-height: 45px;
    padding: 14px;
    color: #333333;
    font-size: 14px;
    line-height: 1.65;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

.journal-empty {
    margin-bottom: 15px;
    padding: 14px;
    color: #666666;
    background: #f8f9fb;
    border: 1px dashed #cfd5dc;
    border-radius: 4px;
    font-style: italic;
}

.journal-denied {
    color: #a94442;
    background: #fdf2f2;
    border-color: #e5b8b8;
}

/* Alerts */
.alert {
    margin-bottom: 22px;
    border-radius: 4px;
}

/* Footer */
.registration-footer {
    padding: 20px 30px;
    background: #ffffff;
    border-top: 1px solid #e6e6e6;
}

/* Back button */
.back-btn {
    padding: 8px 22px;
    color: #f58220;
    background: #ffffff;
    border: 2px solid #f58220;
    border-radius: 5px;
    font-size: 14px;
    font-weight: 600;
    transition:
        background 0.25s ease,
        color 0.25s ease,
        border-color 0.25s ease;
}

.back-btn i {
    margin-right: 8px;
}

.back-btn:hover,
.back-btn:focus,
.back-btn:active {
    color: #ffffff;
    background: #f58220;
    border-color: #f58220;
    outline: none;
    box-shadow: none;
}

/* Tablet */
@media (max-width: 992px) {

    .view-registration-container {
        padding: 18px;
    }

    .registration-header,
    .registration-body,
    .registration-footer {
        padding-left: 20px;
        padding-right: 20px;
    }

    .attachment-card {
        align-items: flex-start;
    }

    .attachment-actions {
        flex-direction: column;
    }

    .attachment-view-btn,
    .attachment-download-btn {
        width: 105px;
    }
}

/* Mobile */
@media (max-width: 768px) {

    .view-registration-container {
        padding: 10px;
    }

    .registration-header {
        padding: 18px;
    }

    .registration-header h2 {
        font-size: 20px;
    }

    .registration-body {
        padding: 18px;
    }

    .registration-footer {
        padding: 18px;
    }

    .attachment-card {
        display: block;
    }

    .attachment-icon {
        margin: 0 0 12px;
    }

    .attachment-name {
        white-space: normal;
        overflow-wrap: anywhere;
    }

    .attachment-metadata {
        display: block;
    }

    .attachment-metadata span {
        display: flex;
        margin-bottom: 6px;
    }

    .attachment-actions {
        display: flex;
        flex-direction: row;
        width: 100%;
        margin: 14px 0 0;
    }

    .attachment-view-btn,
    .attachment-download-btn {
        flex: 1;
        width: auto;
    }

    .journal-entry-header {
        display: block;
    }

    .journal-date {
        display: block;
        margin-top: 7px;
    }

    .back-btn {
        width: 100%;
    }
}

sp_widget.script:
(function() {

    var TABLE =
        "x_1549902_asean_0_learning_application";

    data.fields = [];
    data.journalFields = [];
    data.attachments = [];

    data.recordFound = false;
    data.requestNumber = "";
    data.errorMessage = "";
    data.journalMessage = "";
    data.attachmentMessage = "";

    var sysId = $sp.getParameter("sys_id");

    if (!sysId) {
        data.errorMessage =
            "Learning Application record not specified.";
        return;
    }

    /*
     * Read the Learning Application.
     * GlideRecordSecure respects table and field ACLs.
     */
    var applicationGR =
        new GlideRecordSecure(TABLE);

    if (!applicationGR.get(sysId)) {
        data.errorMessage =
            "Record not found, or you do not have permission to access it.";
        return;
    }

    data.recordFound = true;
    data.requestNumber =
        applicationGR.getDisplayValue("number") || "";

    /*
     * Application fields displayed in this order.
     */
    var fieldOrder = [
        "number",
        "u_employee_name",
        "u_employee_email",
        "u_country",
        "u_manager_email",
        "u_management_l2",
        "manager_approval_l2_required",

        "u_course_title",
        "u_course_type",
        "u_course_format",
        "u_training_country",
        "u_training_provider_name",
        "course_start_date",
        "u_course_end_date",
        "u_total_training_hours",

        "is_payment_required",
        "currency",
        "u_course_fee",
        "u_other_expenses",
        "u_specify_other_expenses",
        "u_total_cost",

        "u_comment",
        "u_status"
    ];

    var addedFields = {};

    /*
     * Add configured fields.
     */
    for (var i = 0; i < fieldOrder.length; i++) {
        addNormalField(fieldOrder[i], i);
    }

    /*
     * Add any additional active fields created directly
     * on the scoped Learning Application table.
     */
    var dictionaryGR =
        new GlideRecord("sys_dictionary");

    dictionaryGR.addQuery("name", TABLE);
    dictionaryGR.addNotNullQuery("element");
    dictionaryGR.addQuery("active", true);
    dictionaryGR.orderBy("position");
    dictionaryGR.orderBy("column_label");
    dictionaryGR.query();

    var nextOrder = fieldOrder.length;

    while (dictionaryGR.next()) {

        var dictionaryField =
            dictionaryGR.getValue("element");

        if (!dictionaryField) {
            continue;
        }

        /*
         * Journal fields are displayed separately.
         */
        if (
            dictionaryField == "comments" ||
            dictionaryField == "work_notes" ||
            dictionaryField == "comments_and_work_notes"
        ) {
            continue;
        }

        if (addedFields[dictionaryField]) {
            continue;
        }

        addNormalField(
            dictionaryField,
            nextOrder++
        );
    }

    /*
     * Read journal entries.
     */
    addJournalField(
        "comments",
        "Additional Comments"
    );

    addJournalField(
        "work_notes",
        "Work Notes"
    );

    /*
     * Check whether any journal history exists.
     */
    var journalEntryCount = 0;

    for (
        var journalIndex = 0;
        journalIndex < data.journalFields.length;
        journalIndex++
    ) {
        journalEntryCount +=
            data.journalFields[journalIndex].entries.length;
    }

    if (journalEntryCount === 0) {
        data.journalMessage =
            "No Additional Comments or Work Notes have been posted.";
    }

    /*
     * Read attachments belonging to this record.
     */
    loadAttachments();

    /*
     * Add a normal field.
     */
    function addNormalField(
        fieldName,
        orderNumber
    ) {

        if (
            !fieldName ||
            addedFields[fieldName] ||
            !applicationGR.isValidField(fieldName)
        ) {
            return;
        }

        var fieldElement =
            applicationGR.getElement(fieldName);

        if (!fieldElement) {
            return;
        }

        /*
         * Respect field read ACL.
         */
        try {
            if (!fieldElement.canRead()) {
                return;
            }
        } catch (fieldReadError) {
            /*
             * Continue when canRead is unavailable.
             */
        }

        var descriptor =
            fieldElement.getED();

        if (!descriptor) {
            return;
        }

        var fieldType =
            descriptor.getInternalType() || "string";

        /*
         * Journal fields are handled separately.
         */
        if (
            fieldType == "journal" ||
            fieldType == "journal_input"
        ) {
            return;
        }

        var rawValue =
            applicationGR.getValue(fieldName);

        var displayValue =
            applicationGR.getDisplayValue(fieldName);

        var isMultiLine =
            fieldType == "html" ||
            fieldType == "translated_html" ||
            fieldType == "string_full_utf8" ||
            fieldType == "translated_text" ||
            fieldType == "script";

        data.fields.push({
            name: fieldName,

            label:
                fieldElement.getLabel() ||
                fieldName,

            value:
                rawValue === null
                    ? ""
                    : rawValue.toString(),

            displayValue:
                displayValue === null
                    ? ""
                    : displayValue.toString(),

            type: fieldType,
            isMultiLine: isMultiLine,
            fullWidth: isMultiLine,
            order: orderNumber
        });

        addedFields[fieldName] = true;
    }

    /*
     * Load Additional Comments or Work Notes
     * directly from sys_journal_field.
     */
    function addJournalField(
        elementName,
        displayLabel
    ) {

        var journalData = {
            name: elementName,
            label: displayLabel,
            entries: [],
            canRead: true
        };

        /*
         * Check the parent journal field ACL.
         */
        if (applicationGR.isValidField(elementName)) {

            try {
                var journalElement =
                    applicationGR.getElement(elementName);

                if (
                    journalElement &&
                    !journalElement.canRead()
                ) {
                    journalData.canRead = false;
                    data.journalFields.push(journalData);
                    return;
                }
            } catch (journalAclError) {
                /*
                 * Continue with the journal query.
                 */
            }
        }

        var journalGR =
            new GlideRecordSecure("sys_journal_field");

        journalGR.addQuery(
            "element_id",
            sysId
        );

        journalGR.addQuery(
            "element",
            elementName
        );

        journalGR.orderByDesc("sys_created_on");
        journalGR.query();

        while (journalGR.next()) {

            var createdByUserName =
                journalGR.getValue("sys_created_by") || "";

            journalData.entries.push({
                sysId:
                    journalGR.getUniqueValue(),

                value:
                    journalGR.getValue("value") || "",

                createdOn:
                    journalGR.getDisplayValue(
                        "sys_created_on"
                    ) || "",

                createdBy:
                    getUserDisplayName(
                        createdByUserName
                    )
            });
        }

        data.journalFields.push(journalData);
    }

    /*
     * Load record attachments.
     */
    function loadAttachments() {

        var attachmentGR =
            new GlideRecordSecure("sys_attachment");

        attachmentGR.addQuery(
            "table_name",
            TABLE
        );

        attachmentGR.addQuery(
            "table_sys_id",
            sysId
        );

        attachmentGR.orderByDesc("sys_created_on");
        attachmentGR.query();

        while (attachmentGR.next()) {

            var attachmentSysId =
                attachmentGR.getUniqueValue();

            var fileName =
                attachmentGR.getValue("file_name") ||
                "Attachment";

            var contentType =
                attachmentGR.getValue("content_type") ||
                "application/octet-stream";

            var sizeBytes =
                parseInt(
                    attachmentGR.getValue("size_bytes"),
                    10
                ) || 0;

            var uploadedByUserName =
                attachmentGR.getValue("sys_created_by") || "";

            data.attachments.push({
                sysId: attachmentSysId,
                fileName: fileName,
                contentType: contentType,

                sizeBytes: sizeBytes,
                sizeDisplay: formatFileSize(sizeBytes),

                uploadedOn:
                    attachmentGR.getDisplayValue(
                        "sys_created_on"
                    ) || "",

                uploadedBy:
                    getUserDisplayName(
                        uploadedByUserName
                    ),

                viewUrl:
                    "/sys_attachment.do?sys_id=" +
                    attachmentSysId,

                downloadUrl:
                    "/sys_attachment.do?sys_id=" +
                    attachmentSysId
            });
        }

        if (data.attachments.length === 0) {
            data.attachmentMessage =
                "No attachments are available for this record.";
        }
    }

    /*
     * Convert bytes to readable file size.
     */
    function formatFileSize(sizeBytes) {

        if (!sizeBytes || sizeBytes < 1) {
            return "0 KB";
        }

        if (sizeBytes < 1024) {
            return sizeBytes + " bytes";
        }

        if (sizeBytes < 1048576) {
            return (
                Math.round(
                    sizeBytes / 1024 * 10
                ) / 10
            ) + " KB";
        }

        if (sizeBytes < 1073741824) {
            return (
                Math.round(
                    sizeBytes / 1048576 * 10
                ) / 10
            ) + " MB";
        }

        return (
            Math.round(
                sizeBytes / 1073741824 * 10
            ) / 10
        ) + " GB";
    }

    /*
     * Convert sys_created_by username to user display name.
     */
    function getUserDisplayName(userName) {

        if (!userName) {
            return "";
        }

        var userGR =
            new GlideRecord("sys_user");

        userGR.addQuery(
            "user_name",
            userName
        );

        userGR.setLimit(1);
        userGR.query();

        if (userGR.next()) {
            return (
                userGR.getDisplayValue() ||
                userName
            );
        }

        return userName;
    }

})();
